package snownee.jade.gui;

import java.net.URI;
import java.time.LocalDate;
import java.util.List;
import java.util.Objects;

import org.apache.commons.lang3.mutable.MutableInt;
import org.jspecify.annotations.Nullable;

import com.google.common.collect.Lists;

import it.unimi.dsi.fastutil.ints.IntArrayList;
import it.unimi.dsi.fastutil.ints.IntList;
import net.minecraft.ChatFormatting;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.components.Tooltip;
import net.minecraft.client.gui.screens.ConfirmLinkScreen;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.resources.language.I18n;
import net.minecraft.client.resources.sounds.SimpleSoundInstance;
import net.minecraft.network.chat.CommonComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.chat.Style;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.util.ARGB;
import net.minecraft.util.Mth;
import net.minecraft.util.RandomSource;
import net.minecraft.util.StringDecomposer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import snownee.jade.Jade;
import snownee.jade.api.config.IWailaConfig;
import snownee.jade.impl.WailaClientRegistration;
import snownee.jade.util.JadeIcons;
import snownee.jade.util.ModIdentification;
import snownee.jade.util.SmoothChasingValue;

public class HomeConfigScreen extends Screen {

	private final RandomSource random = RandomSource.create(42);
	private final @Nullable Screen parent;
	private final ItemStack profileIcon = JadeIcons.of(Items.PAPER);
	private final SmoothChasingValue titleY;
	private final List<TextParticle> particles = Lists.newArrayList();
	private final List<TextParticle> pendingParticles = Lists.newArrayList();
	private final List<TextParticle> persistentParticles = Lists.newArrayList();
	private float ticks;
	private byte festival;
	private float nextParticleIn;
	private boolean showTranslators;
	private int lastMouseX;
	private int lastMouseY;

	public HomeConfigScreen(@Nullable Screen parent) {
		super(Component.translatable("gui.jade.configuration"));
		this.parent = parent;
		titleY = new SmoothChasingValue().start(8).target(32).withSpeed(0.1F);

		if (!WailaClientRegistration.instance().maybeLowVisionUser()) {
			LocalDate now = LocalDate.now();
			int month = now.getMonthValue();
			int day = now.getDayOfMonth();
			if (month == 12 && day >= 24 && day <= 26) {
				festival = 1;
			} else if (month == 6 && (day == 1 || day == 28)) {
				festival = 2;
			} else if (month <= 2 && isLunarNewYear(now)) {
				festival = 99;
			}
		}
	}

	private static boolean isLunarNewYear(LocalDate now) {
		int year = now.getYear();
		int newYearMonthAndDay = switch (year) {
			case 2026 -> 217;
			case 2027 -> 206;
			case 2028 -> 126;
			case 2029 -> 213;
			case 2030 -> 203;
			case 2031 -> 123;
			case 2032 -> 211;
			case 2033 -> 131;
			case 2034 -> 219;
			case 2035 -> 208;
			case 2036 -> 128;
			case 2037 -> 215;
			case 2038 -> 204;
			case 2039 -> 124;
			case 2040 -> 212;
			case 2041 -> 201;
			case 2042 -> 122;
			case 2043 -> 210;
			default -> 0;
		};
		if (newYearMonthAndDay == 0) {
			return false;
		}
		int newYearMonth = newYearMonthAndDay / 100;
		int newYearDay = newYearMonthAndDay % 100;
		LocalDate newYearDate = LocalDate.of(year, newYearMonth, newYearDay);
		int newYearDayOfYear = newYearDate.getDayOfYear();
		int dayOfYear = now.getDayOfYear();
		return dayOfYear >= newYearDayOfYear - 1 && dayOfYear <= newYearDayOfYear + 2;
	}

	@Override
	protected void init() {
		Objects.requireNonNull(minecraft);
		particles.clear();
		Component modSettings = Component.translatable("gui.jade.jade_settings");
		Component pluginSettings = Component.translatable("gui.jade.plugin_settings");
		Component profileSettings = Component.translatable("gui.jade.profile_settings");
		int maxWidth = Math.max(100, Math.max(font.width(modSettings) + 8, font.width(pluginSettings) + 8));
		maxWidth = Math.min(maxWidth, Math.min(240, width / 2 - 40));

		addRenderableWidget(Button.builder(
				modSettings, w -> {
					visitedChildScreen();
					minecraft.gui.setScreen(new WailaConfigScreen(HomeConfigScreen.this));
				}).bounds(width / 2 - 5 - maxWidth, height / 2 - 10, maxWidth, 20).build());
		addRenderableWidget(Button.builder(
				pluginSettings, w -> {
					visitedChildScreen();
					minecraft.gui.setScreen(new PluginsConfigScreen(HomeConfigScreen.this));
				}).bounds(width / 2 + 5, height / 2 - 10, maxWidth, 20).build());
		Button profileButton = new Button(
				width / 2 + 10 + maxWidth,
				height / 2 - 10,
				20,
				20,
				profileSettings,
				_ -> {
					visitedChildScreen();
					minecraft.gui.setScreen(new ProfileConfigScreen(HomeConfigScreen.this));
				},
				Button.DEFAULT_NARRATION) {
			@Override
			public void extractContents(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float a) {
				extractDefaultSprite(graphics);
				graphics.fakeItem(profileIcon, getX() + 2, getY() + 2);
			}
		};
		profileButton.setTooltip(Tooltip.create(profileSettings));
		addRenderableWidget(profileButton);
		addRenderableWidget(Button.builder(CommonComponents.GUI_DONE, w -> onClose())
				.bounds(width / 2 - 50, height / 2 + 20, 100, 20)
				.build());

		Style style = Style.EMPTY;
		if (festival != 0 && festival != 1) {
			style = style.withColor(0xF1E3A4);
		}
		Component title = Component.translatable("gui.jade.by", Component.literal("❤").withStyle(ChatFormatting.RED)).withStyle(style);
		Component hoveredTitle = Component.translatable("gui.jade.by.hovered").withStyle(style);
		int btnWidth = font.width(title);
		int btnX = (int) (width * 0.5F - btnWidth * 0.5F);
		int btnY = (int) (height * 0.9F - 5);
		Component narration = Component.translatable(festival == 99 ? "narration.jade.by.lunar" : "narration.jade.by");
		CreditButton creditButton = addRenderableWidget(new CreditButton(
				btnX,
				btnY,
				btnWidth,
				10,
				title,
				hoveredTitle,
				b -> ConfirmLinkScreen.confirmLinkNow(this, URI.create("https://www.curseforge.com/members/snownee_/projects")),
				this::triggerAuthorButton,
				$ -> narration.copy()));
		if (showTranslators) {
			creditButton.showTranslators();
		}
	}

	private void visitedChildScreen() {
		titleY.set(titleY.getTarget());
		showTranslators = true;
	}

	private void triggerAuthorButton(Button button) {
		if (festival == 2 || festival == 3) {
			festival = 3;
			return;
		}
		IntList colors = new IntArrayList();
		String text = "❄";
		if (festival == 99) {
			for (int i = 0; i < 11; i++) {
				colors.add(random.nextBoolean() ? 0xA80000 : 0xC01800);
			}
			text = "✐";
		} else {
			for (int i = 0; i < 11; i++) {
				colors.add(ARGB.colorFromFloat(1, 1 - random.nextFloat() * 0.6F, 1, 1));
			}
		}
		for (int color : colors) {
			int ox = random.nextIntBetweenInclusive(-button.getWidth() / 2, button.getWidth() / 2);
			float x = width * 0.5F + ox;
			float y = random.nextIntBetweenInclusive(button.getY(), button.getY() + button.getHeight());
			float dx = ox * 0.08F;
			float dy = -5 - random.nextFloat() * 3;
			var particle = new TextParticle(text, x, y, dx, dy, color, 0.75F + random.nextFloat() * 0.5F);
			particles.add(particle);
			if (festival == 99) {
				particle.age = 8 + random.nextFloat() * 5;
			}
		}
	}

	@Override
	public void onClose() {
		IWailaConfig.get().save();
		WailaClientRegistration.instance().reloadIgnoreLists();
		Objects.requireNonNull(minecraft).gui.setScreen(parent);
	}

	@Override
	public void extractRenderState(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTicks) {
		Objects.requireNonNull(minecraft);
		float deltaTicks = Minecraft.getInstance().getDeltaTracker().getRealtimeDeltaTicks();
		ticks += deltaTicks;
		particle:
		if (ticks > nextParticleIn) {
			if (festival == 3) {
				nextParticleIn = ticks;
				if (pendingParticles.isEmpty()) {
					festival3populateNew();
				}
				if (Mth.abs(mouseX - lastMouseX) < 3 && Mth.abs(mouseY - lastMouseY) < 3) {
					break particle;
				}
				lastMouseX = mouseX;
				lastMouseY = mouseY;
				TextParticle particle = pendingParticles.removeFirst();
				particle.x = mouseX;
				particle.y = mouseY;
				particle.gravity = 0F;
				particle.age = 40;
				particles.add(particle);
				persistentParticles.add(particle);
				if (persistentParticles.size() > 50) {
					TextParticle first = persistentParticles.removeFirst();
					first.persistent = false;
				}
			} else if (festival == 1) {
				nextParticleIn = ticks + 10 + random.nextFloat() * 10;
				int color = ARGB.colorFromFloat(1, 1 - random.nextFloat() * 0.6F, 1, 1);
				color |= (random.nextInt(80) + 40) << 24;
				int x = random.nextIntBetweenInclusive(40, width + 100);
				var particle = new TextParticle("❄", x, -20, -0.3F, 0.5f, color, 2F + random.nextFloat());
				particle.gravity = 0F;
				particles.add(particle);
			}
		}
		super.extractRenderState(graphics, mouseX, mouseY, partialTicks);
		int left = width / 2 - 105;
		int top = height / 4 - 20;
		graphics.pose().pushMatrix();
		graphics.pose().translate(left, top);

		float scale = 2F;
		graphics.pose().scale(scale);
		graphics.text(font, ModIdentification.getModFullName(Jade.ID).orElse("Jade"), 0, 0, 0xFFFFFFFF);

		graphics.pose().scale(0.5F);
		titleY.tick(deltaTicks);
		String desc2 = I18n.get("gui.jade.configuration.desc2");
		float scaledX, scaledY;
		if (desc2.isEmpty()) {
			graphics.pose().popMatrix();
			graphics.pose().pushMatrix();
			graphics.pose().translate(left, top);
			scaledX = mouseX - left;
			scaledY = mouseY - top;
		} else {
			scaledX = (mouseX - left) / scale * 2;
			scaledY = (mouseY - top) / scale * 2;
		}
		drawFancyTitle(graphics, I18n.get("gui.jade.configuration.desc1"), Math.min(titleY.value, 20F), 20F, scaledX, scaledY);
		if (!desc2.isEmpty()) {
			drawFancyTitle(graphics, desc2, Math.min(titleY.value + 3F, 32F), 32F, scaledX, scaledY);
		}
		graphics.pose().popMatrix();

		particles.removeIf(p -> {
			p.tick(deltaTicks);
			if (p.y > height + 20) {
				return true;
			}
			p.render(graphics, font, mouseX, mouseY);
			return false;
		});
	}

	private void festival3populateNew() {
		IntList colors = new IntArrayList();
		String text = random.nextBoolean() ? "UwU" : "OwO";
		switch (random.nextInt(7)) {
			case 0 -> {
				colors.add(0xE40303);
				colors.add(0xFF8C00);
				colors.add(0xFFED00);
				colors.add(0x008026);
				colors.add(0x732982);
				colors.add(0x732982);
			}
			case 1 -> {
				colors.add(0x5BCEFA);
				colors.add(0xF5A9B8);
				colors.add(0xFFFFFF);
				colors.add(0xF5A9B8);
				colors.add(0x5BCEFA);
			}
			case 2 -> {
				colors.add(0xD60270);
				colors.add(0xD60270);
				colors.add(0x9B4F96);
				colors.add(0x0038A8);
				colors.add(0x0038A8);
			}
			case 3 -> {
				colors.add(0xFF218C);
				colors.add(0xFF218C);
				colors.add(0xFFD800);
				colors.add(0xFFD800);
				colors.add(0x21B1FF);
				colors.add(0x21B1FF);
			}
			case 4 -> {
				colors.add(0x000000);
				colors.add(0xA3A3A3);
				colors.add(0xFFFFFF);
				colors.add(0x800080);
			}
			case 5 -> {
				colors.add(0xFF76A4);
				colors.add(0xFFFFFF);
				colors.add(0xC011D7);
				colors.add(0x000000);
				colors.add(0x2F3CBE);
			}
			case 6 -> {
				colors.add(0xFCF434);
				colors.add(0xFFFFFF);
				colors.add(0x9C59D1);
				colors.add(0x2C2C2C);
			}
		}
		for (int color : colors) {
			for (int i = 0; i < 5; i++) {
				float rot = random.nextFloat() * Mth.TWO_PI;
				float dx = Mth.cos(rot) * 2;
				float dy = Mth.sin(rot) * 2;
				var particle = new TextParticle(text, 0, 0, dx, dy, color | 0xFF000000, 1);
				pendingParticles.add(particle);
			}
		}
	}

	private void drawFancyTitle(GuiGraphicsExtractor guiGraphics, String text, float y, float expectY, float mouseX, float mouseY) {
		float distY = Math.abs(y - expectY);
		if (distY >= 9) {
			return;
		}
		int color = IWailaConfig.Overlay.applyAlpha(0xFFAAAAAA, 1 - distY / 10F);
		float glint1 = (ticks - y / 5F) % 90 / 45 * width;
		float glint2 = mouseX;
		float glint1Strength = 1;
		float glint2Strength = 1 - Mth.clamp(Math.abs(mouseY - y) / 20F, 0, 1);

		MutableComponent component = Component.empty();
		MutableInt curX = new MutableInt();
		StringDecomposer.iterateFormatted(
				text, Style.EMPTY, (index, style, codePoint) -> {
					String s = Character.toString(codePoint);
					int width = font.width(s);
					int curXVal = curX.intValue();
					curX.add(width);
					curXVal += width / 2;
					float dist = Math.abs(curXVal - glint1);
					float localGlint1 = 0.65F + Mth.clamp(1 - dist / 20, 0, 1) * 0.35F * glint1Strength;
					dist = Math.abs(curXVal - glint2);
					float localGlint2 = 0.65F + Mth.clamp(1 - dist / 20, 0, 1) * 0.35F * glint2Strength;
					float colorMul = Math.max(localGlint1, localGlint2);
					int originalColor = style.getColor() == null ? 0xAAAAAA : style.getColor().getValue();
					component.append(Component.literal(s).withStyle(style).withColor(ARGB.scaleRGB(originalColor, colorMul)));
					return true;
				});

		guiGraphics.pose().pushMatrix();
		guiGraphics.pose().translate(0, y);
		guiGraphics.text(font, component, 0, 0, color);
		guiGraphics.pose().popMatrix();
	}

	private class TextParticle {
		private float age;
		private String text;
		private float x;
		private float y;
		private float motionX;
		private float motionY;
		private int color;
		private float scale;
		private float gravity = 0.98F;
		private boolean persistent = true;
		private float fade = 1;

		public TextParticle(String text, float x, float y, float motionX, float motionY, int color, float scale) {
			this.text = text;
			this.x = x;
			this.y = y;
			this.motionX = motionX;
			this.motionY = motionY;
			this.color = color;
			this.scale = scale;
		}

		private void tick(float partialTicks) {
			x += motionX * partialTicks;
			y += motionY * partialTicks;
			motionY += gravity * partialTicks;
			if (festival == 3) {
				motionX *= 0.88F;
				motionY *= 0.88F;
				if (age < 0) {
					persistent = false;
				}
			}
			boolean greaterThanZero = age > 0;
			age -= partialTicks;
			if (festival == 99) {
				if (greaterThanZero && age <= 0) {
					text = random.nextBoolean() ? "✴" : "✳";
					color = random.nextBoolean() ? 0xFFD427 : 0xF0C415;
					Objects.requireNonNull(minecraft);
					minecraft.getSoundManager().play(SimpleSoundInstance.forUI(
							random.nextBoolean() ?
									SoundEvents.FIREWORK_ROCKET_BLAST :
									SoundEvents.FIREWORK_ROCKET_LARGE_BLAST, 0.7F));
				}
			}
			if (!persistent) {
				fade = Math.max(0, fade - partialTicks * 0.25F);
			}
		}

		private void render(GuiGraphicsExtractor graphics, Font font, int mouseX, int mouseY) {
			if (festival == 99 && age < -4) {
				return;
			}
			graphics.pose().pushMatrix();
			graphics.pose().translate(x, y);
			graphics.pose().scale(scale);
			int color = this.color;
			if (festival == 1) {
				graphics.pose().rotate(age / 50);
				float alpha = Mth.clamp((Math.abs(mouseX - x) + Math.abs(mouseY - y)) / 50F, 0.25F, 1);
				color = IWailaConfig.Overlay.applyAlpha(color, alpha);
			} else if (fade != 1) {
				color = IWailaConfig.Overlay.applyAlpha(color, fade);
			}
			graphics.text(font, text, 0, 0, color);
			graphics.pose().popMatrix();
		}
	}

}

package snownee.jade.gui;

import org.jspecify.annotations.Nullable;

import net.minecraft.client.KeyMapping;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractStringWidget;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.components.StringWidget;
import net.minecraft.client.gui.screens.ConfirmScreen;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.resources.language.I18n;
import net.minecraft.network.chat.Component;
import snownee.jade.Jade;
import snownee.jade.JadeClient;
import snownee.jade.api.JadeKeys;
import snownee.jade.api.config.IWailaConfig;
import snownee.jade.api.ui.JadeUI;
import snownee.jade.gui.config.OptionsList;
import snownee.jade.gui.config.value.OptionValue;
import snownee.jade.impl.config.WailaConfig;
import snownee.jade.util.JsonConfig;

public class ProfileConfigScreen extends BaseOptionsScreen {

	private @Nullable OptionValue<Boolean> enabledEntry;

	public ProfileConfigScreen(Screen parent) {
		super(parent, Component.translatable("gui.jade.profile_settings"));
		diskWriter = () -> IWailaConfig.get().save();
		saver = () -> {
			for (OptionsList.Entry entry : options().children()) {
				if (entry instanceof ProfileEntry profileEntry) {
					profileEntry.save();
				}
			}
			KeyMapping.resetMapping();
			Minecraft.getInstance().options.save();
		};
		boolean enabled = Jade.rootConfig().isEnableProfiles();
		int index = Jade.rootConfig().profileIndex;
		Runnable runnable = JadeClient.recoverKeysAction($ -> JadeKeys.openConfig().getCategory().equals($.getCategory()));
		canceller = () -> {
			if (enabled) {
				Jade.useProfile(index);
			} else {
				Jade.rootConfig().setEnableProfiles(false);
			}
			runnable.run();
		};
	}

	@Override
	public OptionsList createOptions(OptionsList options) {
		WailaConfig.Root root = Jade.rootConfig();
		options.title("profiles");
		enabledEntry = options.choices(
				"enable_profiles", root::isEnableProfiles, value -> {
					Jade.rootConfig().setEnableProfiles(value);
					refresh();
				});
		for (int i = 0; i < JadeClient.profiles.length; i++) {
			options.add(new ProfileEntry(i));
		}

		options.title("key_binds");
		for (KeyMapping keyMapping : JadeClient.profiles) {
			options.keybind(keyMapping);
		}

		return options;
	}

	@Override
	protected void init() {
		super.init();
		refresh();
	}

	public void refresh() {
		boolean enabled = Jade.rootConfig().isEnableProfiles();
		for (OptionsList.Entry entry : options().children()) {
			if (entry != enabledEntry) {
				entry.setDisabled(!enabled);
				if (entry instanceof ProfileEntry profileEntry) {
					profileEntry.refresh();
				}
			}
		}
	}

	public static class ProfileEntry extends OptionsList.Entry {
		public static final Component USE = Component.translatable("gui.jade.profile.use");
		public static final Component SAVE = Component.translatable("selectWorld.edit.save");
		private final int index;
		private final NotUglyEditBox editBox;
		private final @Nullable String originalName;

		public ProfileEntry(int index) {
			super(new StringWidget(Component.translatable("config.jade.profile." + index), Minecraft.getInstance().font));
			this.index = index;

			editBox = new NotUglyEditBox(font, 0, 0, 150, 20, title());
			editBox.fixedTextX = 4;
			editBox.fixedTextY = 7;
			editBox.fixedInnerWidth = editBox.getWidth() - 4 - 12;

			StringWidget titleWidget = (StringWidget) title;
			titleWidget.setMaxWidth(editBox.fixedInnerWidth, StringWidget.TextOverflow.CLAMPED);

			editBox.backgroundMode = NotUglyEditBox.BackgroundMode.HOVERING;
			editBox.setMaxLength(WailaConfig.MAX_NAME_LENGTH);
			editBox.setHint(title());
			editBox.setResponder(_ -> refresh());
			String name = Jade.configs().get(index).get().getName();
			if (name.startsWith("@")) {
				editBox.setValue(I18n.get(name.substring(1)));
				originalName = editBox.getValue();
			} else {
				editBox.setValue(name);
				originalName = null;
			}
			addWidget(new OptionsList.EntryWidget(editBox, 6, -editBox.getHeight() / 2, false));

			addWidget(
					Button.builder(
							USE, _ -> {
								Jade.useProfile(index);
								if (Minecraft.getInstance().gui.screen() instanceof ProfileConfigScreen screen) {
									screen.refresh();
								}
							}).size(48, 20).build(), 0);

			addWidget(
					Button.builder(
							SAVE, _ -> {
								if (JadeUI.hasControlDown()) {
									Jade.saveProfile(index);
									return;
								}
								Minecraft mc = Minecraft.getInstance();
								Screen screen = mc.gui.screen();
								mc.gui.setScreen(new ConfirmScreen(
										bl -> {
											if (bl) {
												Jade.saveProfile(index);
											}
											Minecraft.getInstance().gui.setScreen(screen);
										},
										Component.translatable("gui.jade.save_profile.title"),
										Component.translatable("gui.jade.save_profile.message", normalTitle()),
										Component.translatable("gui.continue"),
										Component.translatable("gui.cancel")));
							}).size(48, 20).build(), 100 - 48);
		}

		public void refresh() {
			WailaConfig.Root root = Jade.rootConfig();
			boolean enabled = root.isEnableProfiles();
			boolean current = index == root.profileIndex;
			if (enabled && current) {
				setTitle(normalTitle().copy().withColor(0xFFFFFF55).append(Component.translatable("gui.jade.profile.active")));
			} else {
				setTitle(normalTitle());
			}
			for (AbstractWidget widget : children()) {
				if (widget instanceof AbstractStringWidget) {
					continue;
				}
				if (widget == editBox) {
					editBox.setTextColor(enabled && current ? 0xFFFFFF55 : 0xFFE0E0E0);
					editBox.setEditable(enabled);
				} else if (enabled) {
					widget.active = !current;
				}
			}
		}

		private Component normalTitle() {
			return editBox.getValue().isBlank() ?
					Component.translatable("config.jade.profile." + index) :
					Component.literal(editBox.getValue());
		}

		public void save() {
			JsonConfig<? extends WailaConfig> config = Jade.configs().get(index);
			if (originalName == null || !originalName.equals(editBox.getValue())) {
				config.get().setName(editBox.getValue());
			}
			config.save();
		}
	}

}

package snownee.jade.gui;

import java.util.List;
import java.util.Objects;

import org.jspecify.annotations.Nullable;

import com.google.common.collect.Lists;
import com.mojang.blaze3d.platform.InputConstants;

import net.minecraft.client.gui.ComponentPath;
import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.gui.components.WidgetSprites;
import net.minecraft.client.gui.components.events.GuiEventListener;
import net.minecraft.client.gui.navigation.FocusNavigationEvent;
import net.minecraft.client.gui.navigation.ScreenAxis;
import net.minecraft.client.gui.navigation.ScreenDirection;
import net.minecraft.client.gui.navigation.ScreenRectangle;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.input.KeyEvent;
import net.minecraft.network.chat.CommonComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;
import net.minecraft.util.FormattedCharSequence;
import snownee.jade.api.JadeIds;
import snownee.jade.api.ui.JadeUI;
import snownee.jade.gui.config.BelowOrAboveListEntryTooltipPositioner;
import snownee.jade.gui.config.OptionsList;
import snownee.jade.gui.config.OptionsNav;
import snownee.jade.gui.config.value.OptionValue;
import snownee.jade.overlay.DisplayHelper;

public abstract class BaseOptionsScreen extends Screen {

	protected final @Nullable Screen parent;
	public @Nullable Button saveButton;
	protected @Nullable Runnable saver;
	protected @Nullable Runnable diskWriter;
	protected @Nullable Runnable canceller;
	protected @Nullable OptionsList options;
	protected @Nullable OptionsNav optionsNav;
	private @Nullable NotUglyEditBox searchBox;

	public BaseOptionsScreen(@Nullable Screen parent, Component title) {
		super(title);
		this.parent = parent;
	}

	@Override
	protected void init() {
		Objects.requireNonNull(minecraft);
		Objects.requireNonNull(saver);
		double scroll = options == null ? 0 : options.scrollAmount();
		super.init();
		if (options != null) {
			options.removed();
		}
		options = createOptions(new OptionsList(this, minecraft, 120, 0, width - 120, height - 32, 26, diskWriter));
		options.setX(120);
		optionsNav = new OptionsNav(options, 120, height - 32 - 18, 18, 18);
		searchBox = new NotUglyEditBox(font, 0, 0, 120, 18, searchBox, Component.translatable("gui.jade.search")) {
			@Override
			public @Nullable ComponentPath nextFocusPath(FocusNavigationEvent event) {
				if (event instanceof FocusNavigationEvent.ArrowNavigation(ScreenDirection direction, ScreenRectangle _) &&
						direction.getAxis() == ScreenAxis.HORIZONTAL) {
					return null;
				}
				if (event instanceof FocusNavigationEvent.InitialFocus) {
					return null;
				}
				return super.nextFocusPath(event);
			}
		};
		searchBox.setHint(Component.translatable("gui.jade.search.hint"));
		searchBox.setResponder(s -> {
			options.updateSearch(s);
			optionsNav.refresh();
		});
		searchBox.fixedTextX = 12;
		searchBox.fixedTextY = 6;
		searchBox.fixedInnerWidth = searchBox.getWidth() - 12 - 18;
		Identifier searchBoxBackground = JadeIds.JADE("search_box_background");
		searchBox.background = new WidgetSprites(searchBoxBackground, searchBoxBackground);
		searchBox.alwaysRenderCross = true;
		searchBox.updateTextPosition();
		addRenderableWidget(optionsNav);
		addRenderableWidget(searchBox);
		addRenderableWidget(options);

		options.updateSearch(searchBox.getValue());
		optionsNav.refresh();
		options.forceSetScrollAmount(scroll);

		saveButton = addRenderableWidget(Button.builder(
				Component.translatable("gui.jade.save_and_quit").withStyle(style -> style.withColor(0xFFB9F6CA)), w -> {
					OptionValue<?> invalidEntry = options().invalidEntry;
					if (invalidEntry == null) {
						options().save();
						saver.run();
						minecraft.gui.setScreen(parent);
					} else {
						changeFocus(ComponentPath.path(Objects.requireNonNull(invalidEntry.mainWidget()), invalidEntry, options(), this));
						options().scrollToEntry(invalidEntry);
					}
				}).bounds(width - 100, height - 25, 90, 20).build());
		if (canceller != null) {
			addRenderableWidget(Button.builder(CommonComponents.GUI_CANCEL, w -> onClose())
					.bounds(saveButton.getX() - 95, height - 25, 90, 20)
					.build());
		}

		options.updateSaveState();
	}

	public OptionsList options() {
		return Objects.requireNonNull(options);
	}

	public OptionsNav optionsNav() {
		return Objects.requireNonNull(optionsNav);
	}

	@Override
	public void extractRenderState(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float partialTicks) {
		super.extractRenderState(guiGraphics, mouseX, mouseY, partialTicks);

		OptionsList.Entry entry = options().isMouseOver(mouseX, mouseY) ? options().getEntryAt(mouseX, mouseY) : null;
		if ((guiGraphics.hoveredTextStyle == null || guiGraphics.hoveredTextStyle.getHoverEvent() == null) && entry != null) {
			int valueX = entry.getContentX() + entry.getTextX();
			if (mouseX >= valueX && mouseX < valueX + entry.getTextWidth()) {
				List<Component> descs = Lists.newArrayListWithExpectedSize(3);
				descs.addAll(entry.getDescription());
				if (JadeUI.hasShiftDown()) {
					descs.addAll(entry.getDescriptionOnShift());
				}
				if (!descs.isEmpty()) {
					descs.replaceAll(options().builtInVariables()::process);
					setTooltipForNextFrame(guiGraphics, descs, mouseX, mouseY, entry);
				}
			}
		}
	}

	public void setTooltipForNextFrame(
			GuiGraphicsExtractor guiGraphics,
			List<Component> descs,
			int mouseX,
			int mouseY,
			OptionsList.Entry entry) {
		Font font = DisplayHelper.font();
		List<FormattedCharSequence> list = descs.stream().flatMap($ -> font.split($, 255).stream()).toList();
		guiGraphics.setTooltipForNextFrame(font, list, new BelowOrAboveListEntryTooltipPositioner(options(), entry), mouseX, mouseY, false);
	}

	public abstract OptionsList createOptions(OptionsList optionsList);

	@Override
	public boolean mouseScrolled(double mouseX, double mouseY, double deltaX, double deltaY) {
		if (optionsNav().isMouseOver(mouseX, mouseY)) {
			return optionsNav().mouseScrolled(mouseX, mouseY, deltaX, deltaY);
		}
		return options().mouseScrolled(mouseX, mouseY, deltaX, deltaY);
	}

	@Override
	public void onClose() {
		if (canceller != null) {
			canceller.run();
		}
		Objects.requireNonNull(minecraft).gui.setScreen(parent);
	}

	@Override
	public void removed() {
		options().removed();
	}

	@Override
	public boolean shouldCloseOnEsc() {
		return options().selectedKey == null;
	}

	@Override
	public boolean keyPressed(KeyEvent keyEvent) {
		if (options().selectedKey == null) {
			int key = keyEvent.key();
			if (keyEvent.modifiers() == 0 && !(deepGetFocused(getCurrentFocusPath()) instanceof EditBox) && (
					(key >= InputConstants.KEY_0 && key <= InputConstants.KEY_Z) ||
							(key >= InputConstants.KEY_NUMPAD0 && key <= InputConstants.KEY_NUMPAD9))) {
				setFocused(searchBox);
			} else if (key == InputConstants.KEY_F && keyEvent.hasControlDownWithQuirk() && !keyEvent.hasShiftDown() &&
					!keyEvent.hasAltDown()) {
				setFocused(searchBox);
				return true;
			}
		}
		return super.keyPressed(keyEvent);
	}

	public static @Nullable GuiEventListener deepGetFocused(@Nullable ComponentPath path) {
		if (path == null) {
			return null;
		} else if (path instanceof ComponentPath.Path node) {
			return deepGetFocused(node.childPath());
		} else {
			return path.component();
		}
	}
}

package snownee.jade.util;

import java.io.File;
import java.io.FileReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Objects;
import java.util.function.Consumer;
import java.util.function.Supplier;

import org.jspecify.annotations.Nullable;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonElement;
import com.google.gson.Strictness;
import com.mojang.serialization.Codec;
import com.mojang.serialization.JsonOps;

import snownee.jade.Jade;

public class JsonConfig<T> {

	/* off */
	public static final Gson GSON = new GsonBuilder()
			.setPrettyPrinting()
			.serializeNulls()
			.enableComplexMapKeySerialization()
			.setStrictness(Strictness.LENIENT)
			.create();
	/* on */

	private final File file;
	private final Codec<T> codec;
	private final CachedSupplier<T> configGetter;

	public JsonConfig(String fileName, Codec<@Nullable T> codec, @Nullable Consumer<T> onUpdate, Supplier<T> defaultFactory) {
		this.file = new File(CommonProxy.getConfigDirectory(), fileName + (fileName.endsWith(".json") ? "" : ".json"));
		this.codec = codec;
		this.configGetter = new CachedSupplier<>(() -> {
			if (!file.exists()) {
				T def = defaultFactory.get();
				write(file, def, false);
				return def;
			}
			try (FileReader reader = new FileReader(file, StandardCharsets.UTF_8)) {
				T ret = codec.parse(JsonOps.INSTANCE, GSON.fromJson(reader, JsonElement.class)).getOrThrow();
				if (ret == null) {
					ret = defaultFactory.get();
					write(file, ret, false);
				}
				return ret;
			} catch (Throwable e) {
				Jade.LOGGER.error("Failed to read config file %s".formatted(file), e);
				if (file.length() > 0) {
					try {
						//noinspection ResultOfMethodCallIgnored
						file.renameTo(new File(file.getPath() + ".invalid"));
					} catch (Exception ignored) {
					}
				}
				T def = defaultFactory.get();
				write(file, def, false);
				return def;
			}
		});
		configGetter.onUpdate = onUpdate;
		mkdirs(file);
	}

	public JsonConfig(String fileName, Codec<T> codec, @Nullable Consumer<T> onUpdate) {
		this(fileName, codec, onUpdate, () -> JadeCodecs.createFromEmptyMap(codec));
		if (CommonProxy.isDevEnv()) {
			JadeCodecs.createFromEmptyMap(codec); // make sure it works
		}
	}

	public T get() {
		return configGetter.get();
	}

	public void save() {
		saveTo(getFile());
	}

	public void saveTo(File file) {
		write(file, get(), false); // Does not need to invalidate since the saved instance already has updated values
	}

	public void write(File file, T t, boolean invalidate) {
		mkdirs(file);
		Path target = file.toPath();
		Path temp = target.resolveSibling(file.getName() + ".tmp");

		try {
			String json = GSON.toJson(codec.encodeStart(JsonOps.INSTANCE, t).getOrThrow());
			Files.writeString(temp, json, StandardCharsets.UTF_8);
			try {
				Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			} catch (AtomicMoveNotSupportedException e) {
				Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
			}
			if (invalidate) {
				invalidate();
			}
		} catch (Throwable e) {
			Jade.LOGGER.error("Failed to write config file %s".formatted(file), e);
			try {
				Files.deleteIfExists(temp);
			} catch (Throwable ignored) {
			}
		}
	}

	private void mkdirs(File file) {
		if (!file.getParentFile().exists()) {
			//noinspection ResultOfMethodCallIgnored
			file.getParentFile().mkdirs();
		}
	}

	public void invalidate() {
		configGetter.invalidate();
	}

	public File getFile() {
		return file;
	}

	static class CachedSupplier<T> {

		private final Supplier<T> supplier;
		private volatile @Nullable T value;
		private @Nullable Consumer<T> onUpdate;

		public CachedSupplier(Supplier<T> supplier) {
			this.supplier = supplier;
		}

		public T get() {
			T v = value;
			if (v == null) {
				synchronized (this) {
					v = value;
					if (v == null) {
						v = supplier.get();
						Objects.requireNonNull(v);
						// Publish the value before onUpdate runs. onUpdate (WailaConfig::fixData)
						// may re-enter get() through a config listener, and would otherwise
						// re-run the supplier recursively until the stack overflows.
						value = v;
						if (onUpdate != null) {
							onUpdate.accept(v);
						}
					}
				}
			}
			return v;
		}

		public void invalidate() {
			this.value = null;
		}
	}
}

package snownee.jade.gui;

import java.util.List;
import java.util.stream.Stream;

import org.apache.commons.lang3.StringUtils;

import com.mojang.blaze3d.platform.cursor.CursorTypes;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.resources.language.I18n;
import net.minecraft.network.chat.Component;
import net.minecraft.util.RandomSource;
import snownee.jade.api.ui.JadeUI;
import snownee.jade.util.SmoothChasingValue;

public class CreditButton extends Button {
	private final Component hoveredTitle;
	private final OnPress onHover;
	private final SmoothChasingValue progress = new SmoothChasingValue();
	private boolean oldHovered;
	private boolean showTranslators;
	private List<String> translators = List.of();
	private int translatorIndex;
	private float translatorTime;

	protected CreditButton(
			int x,
			int y,
			int width,
			int height,
			Component title,
			Component hoveredTitle,
			OnPress onPress,
			OnPress onHover,
			CreateNarration createNarration) {
		super(x, y, width, height, title, onPress, createNarration);
		this.hoveredTitle = hoveredTitle;
		this.onHover = onHover;
	}

	@Override
	protected void extractContents(GuiGraphicsExtractor guiGraphics, int i, int j, float partialTicks) {
		boolean hovered = isHoveredOrFocused();
		if (!oldHovered && hovered) {
			progress.target(1);
		} else if (!hovered) {
			progress.target(0);
		} else if (progress.value > 0.5F) {
			progress.target(0);
			onHover.onPress(this);
		}
		progress.tick(partialTicks);
		progress.value = Math.min(0.6F, progress.value);
		float alpha = hovered ? 170 : 85;
		if (showTranslators && !translators.isEmpty()) {
			int cycleTime = 60;
			translatorTime += partialTicks;
			if (translatorTime > cycleTime) {
				nextTranslator();
			}
			if (!hovered && translators.size() > 1) {
				if (translatorTime < 5) {
					alpha *= translatorTime / 5;
				} else if (cycleTime - translatorTime < 5) {
					alpha *= (cycleTime - translatorTime) / 5;
				}
				alpha = Math.max(alpha, 17);
			}
		}
		guiGraphics.pose().pushMatrix();
		guiGraphics.pose().translate(getX() + width * 0.5F, getY());
		float scale = 1 + progress.value * 0.2F;
		guiGraphics.pose().scale(scale);
		Component credit = hovered ? hoveredTitle : getMessage();
		Font font = Minecraft.getInstance().font;
		guiGraphics.pose().translate(font.width(credit) * -0.5F, 0);
		guiGraphics.text(font, credit, 0, 0, 0xFFFFFF | (int) alpha << 24);
		guiGraphics.pose().popMatrix();
		oldHovered = hovered;
		if (isHovered()) {
			guiGraphics.requestCursor(CursorTypes.POINTING_HAND);
		}
	}

	public void showTranslators() {
		if (showTranslators) {
			return;
		}
		showTranslators = true;
		if (!JadeUI.hasTranslation("gui.jade.translators") || "placeholder ".equals(I18n.get("gui.jade.translated_by", ""))) {
			return;
		}
		String s = I18n.get("gui.jade.translators");
		if ("Bob, Alice, Charlie".equals(s)) {
			return;
		}
		translators = Stream.of(StringUtils.split(s, ',')).map(String::trim).filter(StringUtils::isNotEmpty).toList();
		if (translators.size() > 1) {
			translatorIndex = RandomSource.create().nextInt(translators.size());
		}
		nextTranslator();
	}

	private void nextTranslator() {
		setMessage(Component.translatable("gui.jade.translated_by", translators.get(translatorIndex)));
		if (translators.size() <= 1) {
			return;
		}
		translatorIndex++;
		if (translatorIndex >= translators.size()) {
			translatorIndex = 0;
		}
		translatorTime = 0;
	}
}

package snownee.jade.gui.config.value;

import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;

import org.jspecify.annotations.Nullable;

import net.minecraft.ChatFormatting;
import net.minecraft.client.gui.narration.NarratedElementType;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.client.gui.narration.NarrationThunk;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.HoverEvent;
import net.minecraft.network.chat.Style;
import net.minecraft.resources.Identifier;
import snownee.jade.api.ui.JadeUI;
import snownee.jade.gui.config.OptionsList;

public abstract class OptionValue<T> extends OptionsList.Entry {

	private static final Component SERVER_FEATURE = Component.literal("* ").withStyle(Style.EMPTY.withColor(ChatFormatting.GRAY)
			.withHoverEvent(new HoverEvent.ShowText(Component.translatable("gui.jade.server_feature"))));
	protected final Supplier<T> getter;
	protected final Consumer<T> setter;
	protected @Nullable Identifier id;
	protected T value;
	protected int indent;
	protected boolean inlineWidget;
	private Component rawTitle;

	public OptionValue(String namespace, String optionName, Supplier<T> getter, Consumer<T> setter) {
		super(namespace, makeTitle(namespace, optionName));
		this.getter = getter;
		this.setter = setter;
		rawTitle = title();
		addMessageKey(optionName);
		String key = makeKey(namespace, optionName + "_desc");
		if (JadeUI.hasTranslation(key)) {
			appendDescription(Component.translatable(key));
		}
	}

	@Override
	public void setDisabled(boolean disabled) {
		super.setDisabled(disabled);
		if (disabled) {
			setTitle(rawTitle.copy().withStyle(ChatFormatting.GRAY));
		} else {
			setTitle(rawTitle);
		}
	}

	public void save() {
		setter.accept(value);
	}

	@Override
	public int getTextX() {
		if (isCardMode()) {
			return super.getTextX();
		}
		return indent + 10;
	}

	@Override
	public boolean isInlineWidget() {
		return inlineWidget;
	}

	@Override
	public void updateNarration(NarrationElementOutput output) {
		super.updateNarration(output);
		if (!description.isEmpty()) {
			output.add(NarratedElementType.HINT, NarrationThunk.from(description));
		}
	}

	public boolean isValidValue() {
		return true;
	}

	@Override
	public OptionsList.Entry parent(OptionsList.Entry parent) {
		super.parent(parent);
		if (parent instanceof OptionValue) {
			indent = ((OptionValue<?>) parent).indent + 12;
		}
		return this;
	}

	public abstract void setValue(T value);

	public abstract void updateValue();

	public void setIndent(int indent) {
		this.indent = indent;
	}

	public void setId(Identifier id) {
		this.id = id;
	}

	public @Nullable Identifier getId() {
		return id;
	}

	@Override
	public List<Component> getDescriptionOnShift() {
		if (id == null) {
			return List.of();
		}
		return List.of(Component.literal(id.toString()).withStyle(ChatFormatting.GRAY));
	}

	public void setServerFeature() {
		setTitle(title().copy().append(SERVER_FEATURE));
	}
}

