public void updateSearch(String search) {
	List<Entry> result = Lists.newArrayList();
	Entry expandTarget = collectSearch(search, result);
	if (result.equals(children())) {
		return;
	}
	clearEntries();
	popup.reset();
	for (Entry entry : result) {
		addEntry(entry);
	}
	if (expandTarget != null) {
		popup.expand(expandTarget, true);
	}
	layoutCards();
	forceSetScrollAmount(0);
}

private @Nullable Entry collectSearch(String search, List<Entry> result) {
	boolean card = displayMode == DisplayMode.CARD;
	if (search.isBlank()) {
		for (Entry entry : entries) {
			if (card && entry.isSecondary()) {
				continue;
			}
			result.add(entry);
			if (card && !(entry instanceof Title)) {
				result.addAll(entry.secondaryOptions());
			}
		}
		return null;
	}
	String[] keywords = search.toLowerCase(Locale.ENGLISH).split("\\s+");
	if (card) {
		List<Entry> results = Lists.newArrayList();
		for (Entry entry : entries) {
			if (entry.isSecondary() || entry instanceof Title) {
				continue;
			}
			if (matches(entry, keywords) || entry.secondaryOptions().stream().anyMatch($ -> matches($, keywords))) {
				results.add(entry);
			}
		}
		if (results.isEmpty()) {
			result.add(noResults());
			return null;
		}
		Entry lastTitle = null;
		for (Entry entry : results) {
			if (entry.parent() instanceof Title title && title != lastTitle) {
				result.add(title);
				lastTitle = title;
			}
			result.add(entry);
			result.addAll(entry.secondaryOptions());
		}
		if (results.size() == 1 && !results.getFirst().secondaryOptions().isEmpty()) {
			return results.getFirst();
		}
		return null;
	}
	Set<Entry> matched = Sets.newLinkedHashSet();
	for (Entry entry : entries) {
		if (matches(entry, keywords)) {
			walkChildren(entry, matched::add);
			Entry current = entry;
			while (current.parent() != null) {
				current = Objects.requireNonNull(current.parent());
				matched.add(current);
			}
		}
	}
	for (Entry entry : entries) {
		if (matched.contains(entry)) {
			result.add(entry);
		}
	}
	if (matched.isEmpty()) {
		result.add(noResults());
	}
	return null;
}

private static boolean matches(Entry entry, String[] keywords) {
	List<String> messages = entry.getMessages();
	for (String keyword : keywords) {
		boolean found = false;
		for (String message : messages) {
			if (message.contains(keyword)) {
				found = true;
				break;
			}
		}
		if (!found) {
			return false;
		}
	}
	return true;
}

private Entry noResults() {
	if (noResultsEntry == null) {
		noResultsEntry = new Title(namespace, Component.translatable("gui.jade.no_results").withStyle(ChatFormatting.GRAY));
	}
	return noResultsEntry;
}

public void updateSaveState() {
	invalidEntry = null;
	for (Entry entry : entries) {
		if (entry instanceof OptionValue<?> value && !value.isValidValue()) {
			invalidEntry = value;
			break;
		}
	}
	if (invalidEntry == null) {
		Objects.requireNonNull(owner.saveButton).setTooltip(null);
	} else {
		Objects.requireNonNull(owner.saveButton).setTooltip(Tooltip.create(Component.translatable("gui.jade.invalid_value_cant_save")));
	}
}

public void resetMappingAndUpdateButtons() {
	for (Entry entry : entries) {
		if (entry instanceof KeybindOptionButton button) {
			button.refresh(selectedKey);
		}
	}
}

@Override
public boolean keyPressed(KeyEvent keyEvent) {
	if (selectedKey != null) {
		if (keyEvent.isEscape()) {
			selectedKey.setKey(InputConstants.UNKNOWN);
		} else {
			selectedKey.setKey(InputConstants.getKey(keyEvent));
		}
		selectedKey = null;
		resetMappingAndUpdateButtons();
		return true;
	}
	return super.keyPressed(keyEvent);
}

@Override
public boolean mouseClicked(MouseButtonEvent event, boolean bl) {
	if (selectedKey != null) {
		selectedKey.setKey(InputConstants.Type.MOUSE.getOrCreate(event.button()));
		this.selectedKey = null;
		resetMappingAndUpdateButtons();
		return false;
	}
	Entry expanded = popup.expanded();
	if (expanded != null && popup.width() > 0 && popup.isInside(event.x(), event.y())) {
		for (Entry option : expanded.secondaryOptions()) {
			if (option.isMouseOver(event.x(), event.y())) {
				return super.mouseClicked(event, bl);
			}
		}
		return true;
	}
	return super.mouseClicked(event, bl) || isMouseOver(event.x(), event.y());
}

